changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_384( p_embedding vector(384), p_collection text, p_cross_collection boolean, p_n int ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_384 <=> p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_384 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_384 <=> p_embedding, topic_id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_768( p_embedding vector(768), p_collection text, p_cross_collection boolean, p_n int ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_768 <=> p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_768 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_768 <=> p_embedding, topic_id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.taxonomy_ann_query_1024( p_embedding vector(1024), p_collection text, p_cross_collection boolean, p_n int ) RETURNS TABLE(topic_id bigint, distance float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT topic_id, (embedding_1024 <=> p_embedding)::float8 AS distance FROM nexus.taxonomy_centroids WHERE embedding_1024 IS NOT NULL AND (CASE WHEN p_cross_collection THEN collection <> p_collection ELSE collection = p_collection END) ORDER BY embedding_1024 <=> p_embedding, topic_id ASC LIMIT p_n $$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_384(vector, text, boolean, int);
DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_768(vector, text, boolean, int);
DROP FUNCTION IF EXISTS nexus.taxonomy_ann_query_1024(vector, text, boolean, int);
